UPDATE wf_form_schema
name = #{name}, schema_json = #{schemaJson}, enabled = #{enabled}, update_by = #{updateBy}, update_time = NOW()
WHERE id = #{id}

UPDATE wf_form_schema
SET enabled = 0, update_time = NOW()
WHERE process_definition_key = #{processDefinitionKey}
  AND activity_id = #{activityId}
  AND enabled = 1
  AND id <> #{excludeId}
